import { useState, useRef } from "react";
import emailjs from "@emailjs/browser";
import Banner from "../pages/Banner";
import { useContact } from "../context/ContactContext";

// ─── EmailJS credentials ───────────────────────────────────────────
// 1. Sign up free at https://www.emailjs.com
// 2. Create a Service  → copy the Service ID  → replace YOUR_SERVICE_ID
// 3. Create a Template → copy the Template ID → replace YOUR_TEMPLATE_ID
//    Template variables to add: {{from_name}}, {{from_email}}, {{phone}},
//                                {{subject}}, {{message}}
// 4. Account → API Keys → copy Public Key   → replace YOUR_PUBLIC_KEY
const EMAILJS_SERVICE_ID  = "YOUR_SERVICE_ID";
const EMAILJS_TEMPLATE_ID = "YOUR_TEMPLATE_ID";
const EMAILJS_PUBLIC_KEY  = "YOUR_PUBLIC_KEY";
// ───────────────────────────────────────────────────────────────────

const EMPTY = { name: "", phone: "", email: "", subject: "", message: "" };

export default function Contact() {
  const formRef = useRef(null);
  const { addSubmission } = useContact();

  const [form, setForm]         = useState(EMPTY);
  const [status, setStatus]     = useState("idle"); // idle | sending | success | error
  const [errorMsg, setErrorMsg] = useState("");

  function handleChange(e) {
    setForm({ ...form, [e.target.name]: e.target.value });
  }

  async function handleSubmit(e) {
    e.preventDefault();
    setStatus("sending");
    setErrorMsg("");

    const templateParams = {
      from_name:  form.name,
      from_email: form.email,
      phone:      form.phone,
      subject:    form.subject,
      message:    form.message,
    };

    try {
      await emailjs.send(
        EMAILJS_SERVICE_ID,
        EMAILJS_TEMPLATE_ID,
        templateParams,
        EMAILJS_PUBLIC_KEY
      );

      // Save to dashboard regardless
      addSubmission(form);
      setStatus("success");
      setForm(EMPTY);
    } catch (err) {
      console.error("EmailJS error:", err);
      // Still save to dashboard even if email fails
      addSubmission(form);
      setStatus("error");
      setErrorMsg("Your message was saved but the email could not be sent. Please check your EmailJS credentials.");
    }
  }

  return (
    <>
      <Banner
        title="Contact Us"
        description="We help agencies scale with high-quality backlinks."
        buttonText="Start Growing"
        buttonLink="https://app.grolinq.com"
      />

      <section className="contact-sec">
        <div className="container">
          <div className="row">

            <div className="col-md-6">
              <div className="content">
                <h1>Contact <span className="yellow">Us</span></h1>
                <p>
                  We'd love to hear from you. Whether you're exploring partnership
                  opportunities, need help with link-building campaigns, or simply
                  have a question about GroLinq, our team is here to support you.
                </p>
                <ul>
                  <li>
                    <span>1</span>
                    <strong>Complete the Contact Form:</strong> Provide your full
                    name, email, phone number, subject and a brief description of
                    your inquiry.
                  </li>
                  <li>
                    <span>2</span>
                    <strong>Submit Your Request:</strong> Once you submit the form,
                    you will receive an acknowledgment email.
                  </li>
                  <li>
                    <span>3</span>
                    <strong>Our Response:</strong> A member of our team will review
                    your request and respond within 24 hours.
                  </li>
                </ul>
              </div>
            </div>

            <div className="col-md-6">
              <div className="form_block">
                <h2>Get in Touch</h2>
                <p>Simply fill out the form below, and we'll get back to you as soon as possible.</p>

                {status === "success" ? (
                  <div className="contact-success">
                    <div className="contact-success-icon">✅</div>
                    <h3>Message Sent!</h3>
                    <p>Thank you, <strong>{form.name || "there"}</strong>. We've received your message and will get back to you within 24 hours.</p>
                    <button
                      className="db-btn-primary"
                      style={{ marginTop: 16 }}
                      onClick={() => setStatus("idle")}
                    >
                      Send Another Message
                    </button>
                  </div>
                ) : (
                  <form ref={formRef} onSubmit={handleSubmit}>

                    {status === "error" && (
                      <div className="contact-error-msg">{errorMsg}</div>
                    )}

                    <div className="row">
                      <div className="col-sm-6">
                        <div className="form-group">
                          <input
                            type="text"
                            className="form-control"
                            placeholder="Your Name"
                            name="name"
                            value={form.name}
                            onChange={handleChange}
                            required
                          />
                        </div>
                      </div>

                      <div className="col-sm-6">
                        <div className="form-group">
                          <input
                            type="tel"
                            className="form-control"
                            placeholder="Phone Number"
                            name="phone"
                            value={form.phone}
                            onChange={handleChange}
                            required
                          />
                        </div>
                      </div>

                      <div className="col-sm-12">
                        <div className="form-group">
                          <input
                            type="email"
                            className="form-control"
                            placeholder="Your Email"
                            name="email"
                            value={form.email}
                            onChange={handleChange}
                            required
                          />
                        </div>
                      </div>

                      <div className="col-sm-12">
                        <div className="form-group">
                          <input
                            type="text"
                            className="form-control"
                            placeholder="Subject"
                            name="subject"
                            value={form.subject}
                            onChange={handleChange}
                            required
                          />
                        </div>
                      </div>

                      <div className="col-sm-12">
                        <div className="form-group">
                          <textarea
                            className="form-control"
                            rows="5"
                            placeholder="Message"
                            name="message"
                            value={form.message}
                            onChange={handleChange}
                          />
                        </div>
                      </div>

                      <div className="col-sm-12">
                        <div className="form-group default_btn blue_btn">
                          <button
                            className="btn"
                            type="submit"
                            disabled={status === "sending"}
                          >
                            {status === "sending" ? "Sending…" : "Submit Your Inquiry"}
                          </button>
                        </div>
                      </div>
                    </div>
                  </form>
                )}
              </div>
            </div>

          </div>
        </div>
      </section>
    </>
  );
}
